  const mainCrtStyle = document.createElement('style');
  // Fine moulded-plastic grain, embedded so the skin needs no external assets.
  const crtPlasticGrain='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="96" height="96"><filter id="plastic" x="0" y="0" width="100%" height="100%"><feTurbulence type="fractalNoise" baseFrequency=".65" numOctaves="3" seed="11" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".08"/></feComponentTransfer></filter><rect width="96" height="96" filter="url(#plastic)"/></svg>');
  // User-supplied finished bezel strip, embedded unchanged for offline use.
