    style.textContent+=`
      #matrix-monitor-case-burn{position:absolute!important;left:-40px!important;top:auto!important;bottom:-36px!important;width:108px!important;height:96px!important;transform:none!important;background:url("data:image/png;base64,") center / 100% 100% no-repeat!important;pointer-events:none!important;mix-blend-mode:multiply!important;opacity:.94!important;mask-image:radial-gradient(ellipse 33% 30% at 51% 51%,black 46%,rgba(0,0,0,.75) 68%,transparent 100%),radial-gradient(ellipse 23% 28% at 68% 34%,rgba(0,0,0,.8) 15%,transparent 100%),radial-gradient(ellipse 16% 18% at 32% 58%,rgba(0,0,0,.7),transparent 100%)!important}
`;
    document.head.appendChild(style);monitor.removeAttribute('aria-hidden');
    for(const detail of monitor.children)if(detail!==art)detail.setAttribute('aria-hidden','true');
    const wear=document.createElement('span');wear.id='matrix-monitor-case-wear';wear.setAttribute('aria-hidden','true');monitor.appendChild(wear);
    const fracture=document.createElement('span');fracture.id='matrix-monitor-case-fracture';fracture.setAttribute('aria-hidden','true');wear.appendChild(fracture);
    for(const id of ['burn','corner']){const detail=document.createElement('span');detail.id='matrix-monitor-case-'+id;detail.setAttribute('aria-hidden','true');wear.appendChild(detail);}
    root.classList.remove('mx-monitor-film');
    document.getElementById('matrix-monitor-film-reflection')?.remove();
    const screen=document.createElement('div');screen.id='matrix-monitor-power-screen';screen.dataset.power='on';screen.setAttribute('aria-hidden','true');
